update public.centers c set
  directory_check = 'ok', checked_at = now(),
  agencies = case when cardinality(c.agencies) = 0 and d.a is not null then d.a else c.agencies end,
  agency_detail = coalesce(c.agency_detail, d.d),
  website = coalesce(nullif(c.website, ''), d.w),
  phone = coalesce(nullif(c.phone, ''), d.p),
  locality = coalesce(nullif(c.locality, ''), d.l)
from d where left(c.id::text, 8) = d.i and c.listing_status = 'directorio';
